import { test, expect } from '@playwright/test';

test.describe('Login with Email or Username', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with email address', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Locate email input using getByLabel
    const emailInput = page.getByLabel(/email or username/i);
    await emailInput.fill('user@example.com');

    // Locate password input using getByLabel
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('SecurePassword123');

    // Locate login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL(/.*\/dashboard/);

    // Verify user is logged in
    const welcomeMessage = page.getByText(/welcome/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user profile icon is visible
    const profileIcon = page.getByRole('button', { name: /profile/i });
    await expect(profileIcon).toBeVisible();
  });

  test('should successfully log in with username', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Locate username input using getByLabel
    const usernameInput = page.getByLabel(/email or username/i);
    await usernameInput.fill('johndoe123');

    // Locate password input using getByLabel
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('SecurePassword123');

    // Locate login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL(/.*\/dashboard/);

    // Verify user is logged in
    const welcomeMessage = page.getByText(/welcome/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user profile icon is visible
    const profileIcon = page.getByRole('button', { name: /profile/i });
    await expect(profileIcon).toBeVisible();
  });

  test('should display error message when login fails with invalid credentials', async ({ page }) => {
    // Locate email input using getByLabel
    const emailInput = page.getByLabel(/email or username/i);
    await emailInput.fill('invaliduser@example.com');

    // Locate password input using getByLabel
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('wrongpassword');

    // Locate login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/invalid credentials|email or username not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is still on login page
    await expect(page).toHaveURL(/.*\/login/);
  });
});
